// Two attempts allowed together cost at most one credit, and only once a call connects (doc Section 4.2 / 3.2).
const prior = $input.first().json || [];
const priorList = Array.isArray(prior) ? prior : (prior && prior.id ? [prior] : []);
const attemptsSoFar = priorList.filter(p => p.delivery_state === 'attempted').length;
const alreadyConnected = priorList.some(p => p.delivery_state === 'connected');

const webhookBody = $node["Webhook - /voice-screen (start call)"].json.body || {};
const candDataRaw = $node["Supabase - Fetch Candidate Details"]?.json;
const candData = Array.isArray(candDataRaw) ? candDataRaw[0] : (candDataRaw || {});
const roundInstances = candData.round_instances || [];
const latestRound = Array.isArray(roundInstances) ? (roundInstances[roundInstances.length - 1] || roundInstances[0]) : roundInstances;
const campaign = latestRound?.campaigns || {};

const isUuid = (val) => typeof val === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(val);

const candidate_phone = webhookBody.candidate_phone || candData.phone || '';
const candidate_name = webhookBody.candidate_name || candData.name || '';
const rawRoundId = webhookBody.round_instance_id || latestRound?.id || null;
const round_instance_id = isUuid(rawRoundId) ? rawRoundId : null;
const rawAccountId = webhookBody.account_id || latestRound?.account_id || candData.account_id || null;
const account_id = isUuid(rawAccountId) ? rawAccountId : '00000000-0000-0000-0000-000000000000';
const rawCandId = webhookBody.candidate_id || candData.id || null;
const candidate_id = isUuid(rawCandId) ? rawCandId : null;
const role_title = webhookBody.role_title || campaign?.name || 'Open Position';
const company_name = webhookBody.company_name || 'ScalePods';
const is_test_call = Boolean(webhookBody.is_test_call);

// Dynamic voice config priority: Webhook payload > Campaign DB config > Defaults
const rawConfig = webhookBody.voice_call_config || campaign?.voice_call_config || {};
const dynamicVoiceConfig = {
  agent_id: rawConfig.agent_id || webhookBody.agent_id || 'agent_Lg812J59k27OXl',
  voice: rawConfig.voice || webhookBody.voice || 'rachel',
  prompt: rawConfig.prompt || webhookBody.prompt || webhookBody.role_context || 'You are an AI recruiter screening a candidate.',
  first_message: rawConfig.first_message || webhookBody.first_message || 'Hi {{candidate_name}}, thank you for taking the time to speak with us today.',
  max_duration_seconds: Number(rawConfig.max_duration_seconds || webhookBody.max_duration_seconds || 300),
  language: rawConfig.language || 'en-US',
  response_eagerness: rawConfig.response_eagerness !== undefined ? Number(rawConfig.response_eagerness) : 0.7,
  responsiveness: rawConfig.responsiveness !== undefined ? Number(rawConfig.responsiveness) : 0.8,
  interruption_sensitivity: rawConfig.interruption_sensitivity !== undefined ? Number(rawConfig.interruption_sensitivity) : 0.5,
  agent_functions: Array.isArray(rawConfig.agent_functions) ? rawConfig.agent_functions : [],
  transcriber_id: rawConfig.transcriber_id || 'trs_deepgram_nova_2',
  boosted_keywords: Array.isArray(rawConfig.boosted_keywords) ? rawConfig.boosted_keywords : [],
  ambient_noise: Boolean(rawConfig.ambient_noise),
  denoise_strength: rawConfig.denoise_strength !== undefined ? Number(rawConfig.denoise_strength) : 1,
  voicemail_detection: rawConfig.voicemail_detection !== undefined ? Boolean(rawConfig.voicemail_detection) : true,
  post_call_analysis: Array.isArray(rawConfig.post_call_analysis) ? rawConfig.post_call_analysis : []
};

// Normalize phone to E.164
const rawPhone = String(candidate_phone || '').replace(/[\s-]/g, '');
const normalizedPhone = rawPhone.startsWith('+') ? rawPhone : (rawPhone ? '+' + rawPhone : '');

// Interpolate variables in prompt and greeting
const populatedPrompt = dynamicVoiceConfig.prompt
  .replace(/\{\{candidate_name\}\}/g, candidate_name || 'Candidate')
  .replace(/\{\{job_title\}\}/g, role_title || 'Open Position')
  .replace(/\{\{company_name\}\}/g, company_name || 'ScalePods');

const populatedGreeting = dynamicVoiceConfig.first_message
  .replace(/\{\{candidate_name\}\}/g, candidate_name || 'Candidate')
  .replace(/\{\{job_title\}\}/g, role_title || 'Open Position')
  .replace(/\{\{company_name\}\}/g, company_name || 'ScalePods');

const dialnexa_payload = {
  phone_number: normalizedPhone,
  agent_id: dynamicVoiceConfig.agent_id,
  voice: dynamicVoiceConfig.voice,
  prompt: populatedPrompt,
  first_message: populatedGreeting,
  max_duration_seconds: dynamicVoiceConfig.max_duration_seconds,
  response_eagerness: dynamicVoiceConfig.response_eagerness,
  responsiveness: dynamicVoiceConfig.responsiveness,
  interruption_sensitivity: dynamicVoiceConfig.interruption_sensitivity,
  agent_functions: dynamicVoiceConfig.agent_functions,
  transcriber_id: dynamicVoiceConfig.transcriber_id,
  boosted_keywords: dynamicVoiceConfig.boosted_keywords,
  ambient_noise: dynamicVoiceConfig.ambient_noise,
  denoise_strength: dynamicVoiceConfig.denoise_strength,
  voicemail_detection: dynamicVoiceConfig.voicemail_detection,
  post_call_analysis: dynamicVoiceConfig.post_call_analysis,
  metadata: {
    candidate_phone: normalizedPhone,
    candidate_name: candidate_name || 'Candidate',
    customer_name: candidate_name || 'Candidate',
    company_name: company_name || 'ScalePods',
    role_title: role_title || 'Open Position',
    job_title: role_title || 'Open Position',
    candidate_id: candidate_id,
    round_instance_id: round_instance_id,
    account_id: account_id,
    is_test_call: is_test_call,
    source: is_test_call ? 'scalepods_voice_test_console' : 'scalepods_campaign_pipeline'
  },
  notes: {
    candidate_phone: normalizedPhone,
    candidate_name: candidate_name || 'Candidate',
    company_name: company_name || 'ScalePods',
    role_title: role_title || 'Open Position',
    candidate_id: candidate_id,
    round_instance_id: round_instance_id,
    account_id: account_id,
    is_test_call: is_test_call,
    source: is_test_call ? 'scalepods_voice_test_console' : 'scalepods_campaign_pipeline'
  }
};

return [{
  json: {
    ...webhookBody,
    candidate_id,
    candidate_name,
    candidate_phone: normalizedPhone,
    role_title,
    company_name,
    round_instance_id,
    account_id,
    is_test_call,
    voice_call_config: dynamicVoiceConfig,
    attempt_number: is_test_call ? 1 : (attemptsSoFar + 1),
    skip_call: is_test_call ? false : (attemptsSoFar >= 2 || alreadyConnected),
    dialnexa_payload
  }
}];

// Handles DialNexa call.completed webhooks and fallback Vapi end-of-call-report
const body = $json.body || {};
const meta = body.metadata || body.notes || body.message?.call?.assistantOverrides?.metadata || body.message?.assistant?.metadata || {};
const connected = Boolean(
  body.status === 'completed' ||
  body.event === 'call.completed' ||
  (body.duration && Number(body.duration) > 0) ||
  (body.message?.endedReason && body.message.endedReason !== 'no-answer' && body.message.endedReason !== 'busy')
);
const transcript = body.transcript || body.data?.transcript || body.message?.transcript || '';
const summary = body.summary || body.data?.summary || body.message?.summary || '';
const endedReason = body.end_reason || body.status || body.message?.endedReason || 'completed';

const isUuid = (val) => typeof val === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(val);

return [{ json: {
  candidate_id: isUuid(meta.candidate_id) ? meta.candidate_id : null,
  round_instance_id: isUuid(meta.round_instance_id) ? meta.round_instance_id : null,
  account_id: isUuid(meta.account_id) ? meta.account_id : '00000000-0000-0000-0000-000000000000',
  is_enterprise: Boolean(meta.is_enterprise || meta.plan_tier === 'enterprise'),
  connected,
  transcript,
  summary,
  ended_reason: endedReason
} }];

// Web Crypto API implementation (no 'require()' or external modules needed)
async function verifySignature() {
  const secret = '1bc3565569fe6c8f397d898335734c7f9f7ea1eacfb66eb9c1db12822c4a821f';
  const headers = $json.headers || {};
  const signatureHeader = (headers['x-dialnexa-signature'] || headers['x-signature'] || '').trim();

  // If Dialnexa sends direct token match
  if (signatureHeader === secret) {
    return [{ json: { ...$json, signature_valid: true } }];
  }

  if (!signatureHeader || !secret) {
    return [{ json: { ...$json, signature_valid: false } }];
  }

  try {
    // 1. Get raw string payload
    const rawPayload = typeof $json.body === 'string' 
      ? $json.body 
      : JSON.stringify($json.body || {});

    // 2. Import secret key using Web Crypto API
    const encoder = new TextEncoder();
    const keyData = encoder.encode(secret);
    const cryptoKey = await crypto.subtle.importKey(
      'raw',
      keyData,
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );

    // 3. Compute HMAC digest
    const signatureBuffer = await crypto.subtle.sign(
      'HMAC',
      cryptoKey,
      encoder.encode(rawPayload)
    );

    // 4. Convert digest buffer to hex string
    const hashArray = Array.from(new Uint8Array(signatureBuffer));
    const computedSignature = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

    const isValid = computedSignature.toLowerCase() === signatureHeader.toLowerCase();

    return [{ json: { ...$json, signature_valid: isValid } }];
  } catch (err) {
    return [{ json: { ...$json, signature_valid: false, error: err.message } }];
  }
}

return await verifySignature();
